css:
@import url("https://fonts.googleapis.com/css2?family=Forum&family=Raleway:wght@400;500;600&display=swap");
:root{--rw:#7C4A4A;--rw2:#633A3A;--bl:#EBD5CF;--bl2:#F5E9E5;--ol:#7C806A;--ow:#FAF6F3;--ink:#2E2424;--gr:#6A5C5A;--ln:#E6D8D3;--h:"Forum",Georgia,serif;--b:"Raleway",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.7;color:var(--ink);background:var(--ow)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:400;margin:0;line-height:1.1}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--rw);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:2px solid var(--rw);outline-offset:3px}
.nav{display:flex;justify-content:space-between;align-items:center;height:84px;position:relative}.logo{font-family:var(--h);font-size:32px;text-decoration:none;color:var(--rw)}
.menu{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-weight:500;font-size:16px}.menu a{text-decoration:none}.menu a:hover{color:var(--rw)}
.burger{display:none;background:none;border:1px solid var(--rw);color:var(--rw);width:44px;height:40px;font-size:20px;cursor:pointer}
.hero{padding:10px 0 80px}.hero .wrap{display:grid;grid-template-columns:.95fr 1.05fr;gap:0;align-items:stretch}
.hero .t{background:var(--bl);padding:60px 50px;display:flex;flex-direction:column;justify-content:center;border-radius:240px 0 0 0}
.hero h1{font-size:clamp(44px,5.4vw,76px);color:var(--rw2)}.hero p{color:var(--gr);font-size:18px;margin:22px 0 30px;max-width:28em}
.hero img{width:100%;height:100%;min-height:520px;object-fit:cover;border-radius:0 0 240px 0}
.btn{display:inline-block;background:var(--rw);color:#fff;text-decoration:none;font:600 16px var(--b);padding:15px 28px;border:0;border-radius:40px;cursor:pointer}.btn.l{background:transparent;color:var(--rw);box-shadow:inset 0 0 0 1px var(--rw)}
.row{display:flex;flex-wrap:wrap;gap:12px}
section{padding:84px 0}.sh{max-width:620px;margin-bottom:34px}.sh h2{font-size:clamp(38px,4.8vw,58px);color:var(--rw2)}.sh p{color:var(--gr);margin:10px 0 0}
.mg{display:grid;grid-template-columns:1fr 340px;gap:40px;align-items:start}.mg>div{min-width:0}
.tabs{display:flex;flex-wrap:wrap;gap:6px;border-bottom:1px solid var(--ln);margin-bottom:10px}.tabs button{font:500 16px var(--b);background:none;border:0;border-bottom:2px solid transparent;padding:10px 16px;cursor:pointer;color:var(--gr);margin-bottom:-1px}
.tabs button[aria-pressed=true]{color:var(--rw2);border-color:var(--rw);font-weight:600}
.cat{display:grid;grid-template-columns:200px 1fr;gap:28px;align-items:start;padding-top:20px}.cat img{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:120px 120px 8px 8px}
.it{display:grid;grid-template-columns:1fr auto auto;gap:4px 18px;align-items:center;padding:18px 0;border-bottom:1px solid var(--ln)}
.it h3{font-size:25px}.it p{grid-column:1/2;margin:0;color:var(--gr);font-size:15px}.it .d{font-size:14px;color:var(--ol);font-weight:600;grid-column:1/2}
.it .pr{font-family:var(--h);font-size:26px;grid-row:1/4;grid-column:2}
.it button{grid-row:1/4;grid-column:3;font:600 15px var(--b);background:#fff;color:var(--rw);border:1px solid var(--rw);border-radius:30px;padding:9px 16px;cursor:pointer;white-space:nowrap}.it button[aria-pressed=true]{background:var(--rw);color:#fff}
.bk{background:#fff;border:1px solid var(--ln);border-radius:20px;padding:24px;position:sticky;top:20px}.bk h3{font-size:30px;color:var(--rw2)}
.bk ul{list-style:none;padding:0;margin:14px 0}.bk li{display:flex;gap:10px;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px dashed var(--ln);font-size:15px}.bk li span{flex:1}
.bk li button{background:none;border:0;color:var(--gr);font-size:20px;cursor:pointer;width:32px;height:32px;border-radius:50%}.bk li button:hover{background:var(--bl2)}
.bk .em{color:var(--gr);font-size:15px}.tot{display:flex;justify-content:space-between;margin:6px 0}.tot b{font-family:var(--h);font-size:30px;font-weight:400}
.bk .btn{width:100%;margin-top:14px;text-align:center}.bk .btn:disabled{opacity:.45;cursor:not-allowed}
.bk label{display:block;font-weight:600;font-size:14px;margin:14px 0 6px}.bk input,.bk select{width:100%;font:16px var(--b);padding:11px;border:1px solid var(--ln);border-radius:10px;background:var(--ow);color:var(--ink)}
.msg{visibility:hidden;margin:12px 0 0;color:var(--ol);font-weight:600;font-size:15px}.msg.on{visibility:visible}
.gift{background:var(--bl2)}.gg{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}.gg>div{min-width:0}
.amts{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:18px}.amts button{font:600 17px var(--b);background:#fff;border:1px solid var(--ln);border-radius:12px;padding:12px 20px;cursor:pointer;color:var(--ink)}.amts button[aria-pressed=true]{background:var(--rw);color:#fff;border-color:var(--rw)}
.gf label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}.gf input,.gf textarea{width:100%;font:16px var(--b);padding:12px;border:1px solid var(--ln);border-radius:10px;margin-bottom:14px;background:#fff;color:var(--ink)}
.vc{aspect-ratio:1.6/1;border-radius:22px;background:var(--rw);color:var(--bl);padding:34px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden;box-shadow:0 30px 60px rgba(99,58,58,.25)}
.vc:before{content:"";position:absolute;right:-60px;top:-60px;width:240px;height:240px;border-radius:50%;border:1px solid rgba(235,213,207,.35)}.vc:after{content:"";position:absolute;right:-20px;top:-20px;width:160px;height:160px;border-radius:50%;border:1px solid rgba(235,213,207,.25)}
.vc .n{font-family:var(--h);font-size:26px}.vc .a{font-family:var(--h);font-size:clamp(50px,7vw,86px);line-height:1;color:#fff}.vc .to{font-size:15px;overflow-wrap:anywhere}.vc .ms{font-style:italic;font-size:15px;margin-top:4px;overflow-wrap:anywhere}
.info .wrap{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px}.info h3{font-size:26px;color:var(--rw2);margin-bottom:8px}.info p{margin:0;color:var(--gr)}
footer{background:var(--rw2);color:var(--bl);padding:34px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero .wrap,.gg{grid-template-columns:1fr}.hero .t{border-radius:120px 0 0 0;padding:50px 30px}.hero img{min-height:320px;border-radius:0 0 120px 0}.mg{grid-template-columns:1fr}.bk{position:static}.info .wrap{grid-template-columns:1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:84px;left:0;right:0;background:var(--ow);flex-direction:column;padding:18px 22px;z-index:30;border-bottom:1px solid var(--ln)}.menu.open{display:flex}.cat{grid-template-columns:1fr}.cat img{display:none}
.it{grid-template-columns:1fr auto}.it .pr{grid-row:1;grid-column:2}.it p,.it .d{grid-column:1/-1}.it button{grid-row:4;grid-column:1/-1;justify-self:start;margin-top:8px}.vc{padding:24px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=500&q=75&auto=format&fit=crop`;
const M={m:{img:["1544161515-4ab6ce6db874","Therapist pouring oil during a back massage"],i:[["Swedish massage","Full body, light to medium pressure",60,95],["Deep tissue","For tight shoulders and backs",60,110],["Hot stone massage","Warm basalt stones and slow strokes",75,125],["Back, neck and shoulders","Quick fix for desk tension",30,55]]},
f:{img:["1616394584738-fc6e612e71b9","Woman relaxing with a face mask during a facial"],i:[["Signature facial","Cleanse, gentle peel, mask and massage",60,90],["Express glow","Short facial before an event",30,50],["Calm skin facial","For sensitive or red skin",45,75]]},
h:{img:["1522337360788-8b13dee7a37e","Woman with long wavy hair after a salon visit"],i:[["Cut and blow dry","Includes wash and style",60,65],["Blow dry","Wash and bouncy blow dry",40,40],["Full colour","One colour, roots to ends, plus blow dry",120,140],["Gloss treatment","Shine and softness, adds 20 minutes",20,30]]},
n:{img:["1604654894610-df63bc536371","Hand with neat dark nail polish"],i:[["Gel manicure","Shape, cuticle care, gel colour",45,45],["Classic pedicure","Soak, scrub, massage and polish",50,55],["Gel removal","Gentle removal and nail care",20,15]]}};
const B=[];let cat='m';const key=(c,i)=>c+i;
function items(){const m=M[cat];$('cimg').src=U(m.img[0]);$('cimg').alt=m.img[1];
$('items').innerHTML=m.i.map((t,i)=>{const on=B.some(b=>b.k===key(cat,i));return`<div class="it"><h3>${t[0]}</h3><span class="pr">$${t[3]}</span><button type="button" data-i="${i}" aria-pressed="${on}" aria-label="${on?'Remove':'Add'} ${t[0]}">${on?'Added ✓':'Add'}</button><p>${t[1]}</p><span class="d">${t[2]} minutes</span></div>`}).join('')}
function basket(){$('bl').innerHTML=B.map((b,i)=>`<li><span>${b.n}<br><small style="color:var(--gr)">${b.m} min</small></span>$${b.p}<button type="button" data-r="${i}" aria-label="Remove ${b.n}">×</button></li>`).join('');
$('be').style.display=B.length?'none':'block';const m=B.reduce((a,b)=>a+b.m,0),p=B.reduce((a,b)=>a+b.p,0);$('tt').textContent=m>=60?`${Math.floor(m/60)} hr ${m%60?m%60+' min':''}`.trim():m+' min';$('tp').textContent='$'+p;$('bb').disabled=!B.length}
$('tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('tabs').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));cat=b.dataset.c;items()};
$('items').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=+b.dataset.i,k=key(cat,i),x=B.findIndex(y=>y.k===k);if(x>-1)B.splice(x,1);else{const t=M[cat].i[i];B.push({k,n:t[0],m:t[2],p:t[3]})}items();basket()};
$('bl').onclick=e=>{const b=e.target.closest('button');if(!b)return;B.splice(+b.dataset.r,1);items();basket()};
items();basket();const nd=new Date(Date.now()+3*864e5);$('bd').value=nd.toISOString().slice(0,10);$('bd').min=new Date().toISOString().slice(0,10);
$('bf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Booked, ${$('bn').value}. ${B.length} treatment${B.length>1?'s':''} on ${$('bd').value} from ${$('bs').value}. Total ${$('tp').textContent}, paid on the day.`;$('msg').classList.add('on')};
let amt=100;function vc(){$('va').textContent='$'+amt;$('vto').textContent=`For ${$('gto').value||'someone special'}, from ${$('gfr').value||'you'}`;$('vm').textContent=$('gm').value}
$('amts').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('amts').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));amt=+b.dataset.a;vc()};
['gto','gfr','gm'].forEach(i=>$(i).addEventListener('input',vc));vc();
$('gf').onsubmit=e=>{e.preventDefault();$('gmsg').textContent=`Done. A $${amt} voucher for ${$('gto').value} is on its way to your inbox.`;$('gmsg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
